// Lit la session Stripe et en déduit la formule et la langue du client.
const s = $input.first().json.data.object;
if (s.payment_status !== 'paid') return [];
const email = String(s.customer_details?.email || '').trim().toLowerCase();
if (!email) throw new Error('Paiement sans e-mail : ' + s.id);
const name = String(s.customer_details?.name || '').trim() || email;
const amount = (s.amount_total || 0) / 100;
// 99 € = vérification ; au-delà de 150 € = formule complète (699 €, ou 600 € si les 99 € sont déduits)
const product = amount > 150 ? 'complete' : 'verification';
const loc = String(s.locale || '').slice(0, 2);
const country = s.customer_details?.address?.country || '';
const FR = ['FR', 'BE', 'LU', 'MC', 'CA', 'MA', 'TN', 'DZ', 'SN', 'CI', 'RE', 'GP', 'MQ', 'GF', 'YT', 'NC', 'PF'];
const DE = ['DE', 'AT', 'CH'];
const lang = ['fr', 'en', 'de'].includes(loc) ? loc : FR.includes(country) ? 'fr' : DE.includes(country) ? 'de' : 'en';
return [{ json: { email, name, product, lang, amount, sessionId: s.id } }];

// 200 = compte créé ; 422 = le client a déjà un compte (2e achat) : on continue.
const r = $input.first().json;
const p = $('Préparer le client').first().json;
const created = r.statusCode >= 200 && r.statusCode < 300;
const exists = r.statusCode === 422 || /already|exists/i.test(JSON.stringify(r.body || ''));
if (!created && !exists) throw new Error(`Création du compte impossible (${r.statusCode}) : ${JSON.stringify(r.body)}`);
return [{ json: { ...p, isNew: created } }];

const SITE = 'https://myvisadtv.com';
const espaceUrl = (lang) => SITE + ({ en: '/en', de: '/de' }[lang] || '') + '/dossier/';
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const first = (n) => esc(String(n || '').trim().split(/\s+/)[0] || '');
const SIGN = { fr: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com', en: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com', de: 'Alexandre<br>MyVisaDTV · contact@myvisadtv.com' };
const HELLO = { fr: 'Bonjour', en: 'Hello', de: 'Hallo' };
function bouton(href, label) {
  return `<p style="margin:28px 0"><a href="${href}" style="background:#16233f;color:#fff;padding:14px 22px;border-radius:999px;text-decoration:none;font-weight:600;display:inline-block">${label}</a></p>`;
}
function mail(lang, name, paras, cta) {
  const l = ['fr', 'en', 'de'].includes(lang) ? lang : 'fr';
  const body = paras.map((p) => `<p style="margin:0 0 14px">${p}</p>`).join('');
  const html = `<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.55;color:#1f2937;max-width:560px">`
    + `<p style="margin:0 0 14px">${HELLO[l]} ${first(name)},</p>${body}${cta ? bouton(cta[0], cta[1]) : ''}<p style="margin:24px 0 0">${SIGN[l]}</p></div>`;
  const text = [`${HELLO[l]} ${String(name || '').split(' ')[0]},`, ...paras.map((p) => p.replace(/<br>/g, '\n').replace(/<[^>]+>/g, '')), cta ? `${cta[1]} : ${cta[0]}` : '', 'Alexandre — MyVisaDTV'].filter(Boolean).join('\n\n');
  return { html, text };
}

const res = $input.first().json;
if (res.statusCode >= 300) throw new Error(`Dossier non créé (${res.statusCode}) : ${JSON.stringify(res.body)}`);
// Stripe renvoie parfois deux fois le même paiement : dossier déjà créé → on s'arrête.
if (!Array.isArray(res.body) || res.body.length === 0) return [];
const c = $('Compte nouveau ou existant ?').first().json;
const L = $('Supabase : lien pour le mot de passe').first().json;
const link = L.action_link || (L.properties && L.properties.action_link);
if (!link) throw new Error('Lien de connexion manquant : ' + JSON.stringify(L));
const espace = espaceUrl(c.lang);
const T = {
  fr: {
    objet: 'Votre espace client MyVisaDTV est prêt',
    merci: `Merci pour votre paiement de <strong>${c.amount} €</strong> (${c.product === 'complete' ? 'formule complète' : 'vérification du dossier'}). Votre espace client est ouvert.`,
    id: `<strong>Identifiant :</strong> ${esc(c.email)}<br><strong>Mot de passe :</strong> ${c.isNew ? 'à choisir vous-même avec le bouton ci-dessous (lien valable 24 h)' : 'celui que vous avez déjà, ou un nouveau avec le bouton ci-dessous'}.`,
    suite: c.product === 'complete'
      ? 'Prochaine étape : déposez vos pièces dans votre espace. Nous préparons ensuite votre dossier et convenons avec vous de la date de dépôt sur le portail officiel e-Visa.'
      : 'Prochaine étape : déposez vos pièces dans votre espace. Dès que votre dossier est complet, vous recevez votre rapport écrit sous 48 h ouvrées.',
    liste: `La liste des pièces par catégorie : <a href="${SITE}/blog/documents-dtv-thailande-liste-complete/">${SITE}/blog/documents-dtv-thailande-liste-complete/</a>`,
    apres: `Ensuite, connectez-vous à tout moment sur <a href="${espace}">${espace}</a>. Lien expiré ? Cliquez sur « Recevoir un lien » sur cette page.`,
    cta: c.isNew ? 'Choisir mon mot de passe' : 'Ouvrir mon espace',
  },
  en: {
    objet: 'Your MyVisaDTV client space is ready',
    merci: `Thank you for your payment of <strong>${c.amount}€</strong> (${c.product === 'complete' ? 'full package' : 'document check'}). Your client space is open.`,
    id: `<strong>Login:</strong> ${esc(c.email)}<br><strong>Password:</strong> ${c.isNew ? 'choose it yourself with the button below (link valid for 24 hours)' : 'your existing one, or set a new one with the button below'}.`,
    suite: c.product === 'complete'
      ? 'Next step: upload your documents to your space. We then prepare your file and agree with you on the filing date on the official e-Visa portal.'
      : 'Next step: upload your documents to your space. As soon as your file is complete, you get your written report within 48 business hours.',
    liste: `Document list by category: <a href="${SITE}/en/blog/">${SITE}/en/blog/</a>`,
    apres: `After that, log in any time at <a href="${espace}">${espace}</a>. Link expired? Click “Get a link” on that page.`,
    cta: c.isNew ? 'Choose my password' : 'Open my space',
  },
  de: {
    objet: 'Ihr MyVisaDTV-Kundenbereich ist bereit',
    merci: `Vielen Dank für Ihre Zahlung von <strong>${c.amount} €</strong> (${c.product === 'complete' ? 'Komplettpaket' : 'Prüfung der Unterlagen'}). Ihr Kundenbereich ist eingerichtet.`,
    id: `<strong>Benutzername:</strong> ${esc(c.email)}<br><strong>Passwort:</strong> ${c.isNew ? 'wählen Sie selbst über den Button unten (Link 24 Stunden gültig)' : 'Ihr bisheriges, oder ein neues über den Button unten'}.`,
    suite: c.product === 'complete'
      ? 'Nächster Schritt: Laden Sie Ihre Unterlagen in Ihrem Bereich hoch. Wir bereiten dann Ihren Antrag vor und vereinbaren mit Ihnen den Einreichungstermin im offiziellen e-Visa-Portal.'
      : 'Nächster Schritt: Laden Sie Ihre Unterlagen in Ihrem Bereich hoch. Sobald sie vollständig sind, erhalten Sie Ihren schriftlichen Bericht innerhalb von 48 Werktagsstunden.',
    liste: `Unterlagen nach Kategorie: <a href="${SITE}/de/blog/">${SITE}/de/blog/</a>`,
    apres: `Danach melden Sie sich jederzeit unter <a href="${espace}">${espace}</a> an. Link abgelaufen? Klicken Sie dort auf „Link erhalten“.`,
    cta: c.isNew ? 'Passwort wählen' : 'Bereich öffnen',
  },
}[c.lang] ;
const m = mail(c.lang, c.name, [T.merci, T.id, T.suite, T.liste, T.apres], [link, T.cta]);
return [{ json: {
  to: c.email, objet: T.objet, html: m.html, text: m.text, email: c.email,
  telegram: `💳 Paiement reçu : ${c.name} (${c.email}), ${c.amount} €, ${c.product === 'complete' ? 'formule complète' : 'vérification 99 €'}. Compte ${c.isNew ? 'créé' : 'existant'}, dossier créé, e-mail envoyé.`,
} }];
